window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[96]={"id":"096","numero":96,"titre":"Neuropathies périphériques","objectifs":[{"id":"96-1","rang":"A","rubrique":"Définition","titre":"Connaître la classification et la définition des différents types de neuropathies périphériques","contenu":"<div class=\"notion-course\"><h4>Classer avant de chercher la cause</h4><table><thead><tr><th>Type</th><th>Structure / répartition</th><th>Repère <span class=\"nc-green nc-bold\">clinique</span></th></tr></thead><tbody><tr><td>Mononeuropathie</td><td>Un tronc nerveux.</td><td>Territoire précis ; souvent <span class=\"nc-red nc-bold\">compression</span> ou traumatisme, mais une cause générale reste possible.</td></tr><tr><td>Mononeuropathies <span class=\"nc-yellow_bg\">multiples</span></td><td>Plusieurs troncs, simultanément ou successivement.</td><td>Asymétrie et <span class=\"nc-yellow_bg\">atteinte</span> par territoires, parfois <span class=\"nc-red nc-bold\">douloureuse</span> et rapidement évolutive.</td></tr><tr><td>Polyneuropathie</td><td><span class=\"nc-yellow_bg\">Atteinte</span> diffuse, souvent longueur-dépendante.</td><td><span class=\"nc-red nc-bold\">Distale</span>, <span class=\"nc-red nc-bold\">bilatérale</span> et généralement <span class=\"nc-red nc-bold\">symétrique</span> : pieds avant <span class=\"nc-blue_bg\">mains</span>.</td></tr><tr><td>Polyradiculoneuropathie</td><td>Racines et nerfs périphériques.</td><td><span class=\"nc-yellow_bg\">Atteinte</span> <span class=\"nc-red nc-bold\">proximale</span> et <span class=\"nc-red nc-bold\">distale</span>, souvent aréflexique ; forme <span class=\"nc-red nc-bold\">aiguë</span> ou <span class=\"nc-pink nc-bold\">chronique</span>.</td></tr><tr><td>Neuronopathie sensitive</td><td>Corps cellulaires sensitifs des ganglions rachidiens.</td><td><span class=\"nc-yellow_bg\">Atteinte</span> sensitive non longueur-dépendante, souvent ataxique et <span class=\"nc-red nc-bold\">asymétrique</span>.</td></tr><tr><td><span class=\"nc-yellow_bg\">Neuronopathie motrice</span></td><td>Corps cellulaires moteurs.</td><td><span class=\"nc-blue_bg\">Déficit moteur</span>, <span class=\"nc-red nc-bold\">amyotrophie</span>/<span class=\"nc-blue_bg\">fasciculations</span> ; rechercher signes centraux et diagnostics différentiels.</td></tr></tbody></table><h4>Ajouter trois axes</h4><ul><li>Fibres : sensitive, <span class=\"nc-red nc-bold\">motrice</span>, sensitivo-<span class=\"nc-red nc-bold\">motrice</span> ; grosses fibres proprioceptives ou <span class=\"nc-purple nc-bold\">petites fibres</span> thermoalgiques/autonomes.</li><li>Temps : aigu sur quelques jours/semaines, subaigu ou chronique ; préciser progression, rechutes et ancienneté réelle.</li><li>Mécanisme électrophysiologique : axonal, démyélinisant ou neuronal. La seule topographie ne détermine pas le mécanisme.</li></ul><div class=\"callout\"><p>Une mononeuropathie multiple peut devenir confluente et sembler <span class=\"nc-red nc-bold\">symétrique</span> : reconstituer le début de l’histoire.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Classification clinique et mécanisme séparés ; terminologie corrigée.</p></details>","frequence":1},{"id":"96-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","contenu":"<div class=\"notion-course\"><h4>1. Reconnaître un syndrome <span class=\"nc-red_bg\">neurogène</span> périphérique</h4><table><thead><tr><th>Domaine</th><th>À rechercher</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Moteur</span></td><td>Faiblesse flasque, hypotonie, <span class=\"nc-red nc-bold\">amyotrophie</span> parfois retardée, <span class=\"nc-blue_bg\">crampes</span> et <span class=\"nc-blue_bg\">fasciculations</span> ; réflexes diminués dans les territoires atteints.</td></tr><tr><td><span class=\"nc-red nc-bold\">Sensitif</span></td><td><span class=\"nc-blue_bg\">Paresthésies</span>, <span class=\"nc-blue_bg\">dysesthésies</span>, <span class=\"nc-blue_bg\">brûlures</span>, allodynie ; tester tact, piqûre/température, vibration et sens de position.</td></tr><tr><td>Proprioceptif</td><td><span class=\"nc-blue_bg\">Ataxie</span> sensitive et Romberg aggravé yeux fermés, pseudo-athétose possible ; examiner les grosses <span class=\"nc-purple nc-bold\">fibres</span>.</td></tr><tr><td>Autonome</td><td>Hypotension orthostatique, <span class=\"nc-red_bg\">troubles</span> de sudation, transit, vidange gastrique, vessie et fonction sexuelle.</td></tr><tr><td>Fonctionnel / trophique</td><td>Marche, <span class=\"nc-red nc-bold\">steppage</span>, chutes, déformations, plaies et <span class=\"nc-red_bg\">troubles</span> <span class=\"nc-red_bg\">cutanés</span> ; examiner les pieds.</td></tr></tbody></table><h4>2. Décrire le phénotype et le contexte</h4><ul><li>Symétrique ou <span class=\"nc-red nc-bold\">asymétrique</span> ? Distal ou proximal ? Un nerf, plusieurs nerfs, racines, ou distribution non longueur-dépendante ? <span class=\"nc-red nc-bold\">Moteur</span> pur ou <span class=\"nc-red nc-bold\">sensitif</span> associé ?</li><li>Date de début, vitesse de progression, douleur, infection récente, signes généraux, médicaments/chimiothérapie, <span class=\"nc-orange_bg\">alcool</span>, toxiques, alimentation, diabète et fonction rénale.</li><li>Antécédents familiaux, <span class=\"nc-blue_bg\">pieds creux</span> et <span class=\"nc-red_bg\">troubles</span> anciens ; absence d’antécédent familial ne suffit pas à exclure une maladie génétique.</li></ul><h4>3. Rechercher une urgence avant les examens programmés</h4><p>Faiblesse rapidement ascendante, dyspnée, <span class=\"nc-red_bg\">troubles</span> de déglutition, dysautonomie importante ou <span class=\"nc-yellow_bg\">atteinte</span> multifocale <span class=\"nc-red nc-bold\">douloureuse</span> évolutive : évaluation spécialisée urgente. Un niveau <span class=\"nc-red nc-bold\">sensitif</span>, un Babinski ou un trouble sphinctérien récent font aussi rechercher une cause centrale/compressive.</p><div class=\"callout\"><p>Une neuropathie n’exige pas la triade déficit + <span class=\"nc-blue_bg nc-bold\">aréflexie</span> + <span class=\"nc-red nc-bold\">amyotrophie</span>. Les <span class=\"nc-purple nc-bold\">petites fibres</span> peuvent être atteintes avec force, réflexes et ENMG usuels conservés.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418174b5f2fc2187a2b539?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathie diabétique</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Diagnostic des neuropathies — synthèse et arbre, 2007</a></li></ul><p>Diagnostic clinique enrichi ; urgences et limites de l’ENMG des petites fibres précisées.</p></details>","frequence":0},{"id":"96-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","contenu":"<div class=\"notion-course\"><h4>Distinguer les quatre tableaux principaux</h4><table><thead><tr><th>Tableau</th><th>Distribution</th><th>Examen / suite</th></tr></thead><tbody><tr><td>Polyneuropathie longueur-dépendante</td><td>Pieds puis jambes, <span class=\"nc-blue_bg\">mains</span> plus tard ; symétrie relative.</td><td>Sensibilité souvent au premier plan, achilléens diminués, déficit distal/<span class=\"nc-red_bg\">steppage</span> si avancée. Chercher diabète, alcool, médicaments et causes métaboliques.</td></tr><tr><td>Mononeuropathie</td><td>Territoire d’un nerf.</td><td>Relier muscles, sensibilité et site ; rechercher <span class=\"nc-red nc-bold\">compression</span>/traumatisme. Une douleur aiguë hors canal peut être vasculaire/inflammatoire.</td></tr><tr><td>Mononeuropathies <span class=\"nc-yellow_bg\">multiples</span></td><td>Plusieurs nerfs, <span class=\"nc-red nc-bold\">asymétriques</span> et souvent <span class=\"nc-red nc-bold\">asynchrones</span>.</td><td>Cartographier chaque territoire ; douleur et progression aiguë/subaiguë font craindre une <span class=\"nc-orange_bg\">vascularite</span>. <span class=\"nc-green nc-bold\">ENMG</span> et bilan urgent dirigé.</td></tr><tr><td>Polyradiculoneuropathie</td><td>Proximal et distal, souvent bilatéral, parfois <span class=\"nc-yellow_bg\">nerfs crâniens</span>.</td><td>Faiblesse et <span class=\"nc-blue_bg\">aréflexie</span>, <span class=\"nc-red_bg\">troubles</span> sensitifs/dysautonomiques possibles ; rechercher respiration et déglutition, <span class=\"nc-green nc-bold\">ENMG</span> et LCS selon contexte.</td></tr></tbody></table><h4>La temporalité change l’orientation</h4><ul><li>Installation aiguë rapidement progressive : évoquer notamment Guillain-Barré et hospitaliser selon suspicion, sans attendre tous les résultats. Le LCS et l’ENMG peuvent être non concluants au début.</li><li>Évolution au-delà de 8 semaines ou rechutes : faire discuter une PIDC par le neurologue. Des variantes ne suivent pas parfaitement le tableau <span class=\"nc-red nc-bold\">symétrique</span> proximal classique.</li><li>Une polyneuropathie <span class=\"nc-red nc-bold\">distale</span> <span class=\"nc-pink nc-bold\">chronique</span> typique n’explique pas spontanément une paralysie respiratoire, une <span class=\"nc-yellow_bg\">atteinte</span> bulbaire ou une aggravation rapide : chercher une autre forme/cause.</li></ul><p>Le mécanisme se précise par l’<span class=\"nc-green nc-bold\">ENMG</span> : une polyradiculoneuropathie n’est pas obligatoirement démyélinisante, notamment certaines formes de Guillain-Barré.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3261449/en/polyradiculoneuropathie-inflammatoire-demyelinisante-chronique-pidc\" target=\"_blank\" rel=\"noopener noreferrer\">FILNEMUS · PNDS PIDC, 2021 (hébergé par la HAS)</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Diagnostic des neuropathies — synthèse et arbre, 2007</a></li></ul><p>Seuil PIDC actualisé à 8 semaines ; signes respiratoires et formes axonales rappelés.</p></details>","frequence":2},{"id":"96-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une neuronopathie sensitive (examen clinique, démarche diagnostique)","contenu":"<div class=\"notion-course\"><h4>Reconnaître une ganglionopathie sensitive</h4><p>L’<span class=\"nc-yellow_bg\">atteinte</span> porte sur les corps cellulaires des neurones sensitifs dans les ganglions rachidiens. La distribution ne suit pas la longueur des axones : <span class=\"nc-blue_bg\">mains</span>, <span class=\"nc-blue_bg\">membres supérieurs</span>, <span class=\"nc-blue_bg\">tronc</span> ou face peuvent être atteints tôt, parfois de manière <span class=\"nc-red nc-bold\">asymétrique</span>.</p><ul><li><span class=\"nc-yellow_bg\">Atteinte</span> sensitive pure ou très prédominante ; perte proprioceptive avec <span class=\"nc-blue_bg\">ataxie</span>, gestes mal contrôlés et aggravation yeux fermés.</li><li><span class=\"nc-blue_bg\">Aréflexie</span> souvent diffuse ; la force musculaire est préservée dans une forme sensitive pure, même si l’ataxie gêne les gestes.</li><li>Les <span class=\"nc-red_bg\">troubles</span> thermoalgiques et les <span class=\"nc-blue_bg\">douleurs</span> dépendent des fibres touchées ; la présentation n’est pas toujours exclusivement ataxique.</li></ul><h4>Confirmer et chercher une cause</h4><ol><li>ENMG : potentiels sensitifs réduits ou absents de façon diffuse/non longueur-dépendante, avec conductions <span class=\"nc-red nc-bold\">motrices</span> relativement conservées.</li><li>Rechercher contexte cancéreux, syndrome sec, auto-immunité, médicaments/toxiques et évolution subaiguë.</li><li>Examens dirigés : recherche de cancer et anticorps antineuronaux si suspicion <span class=\"nc-red nc-bold\">paranéoplasique</span>, bilan de Sjögren, bilan toxique. LCS selon avis et hypothèse, pas systématique dans toute <span class=\"nc-red_bg\">ataxie</span>.</li></ol><div class=\"callout\"><p>Une <span class=\"nc-red_bg\">ataxie</span> n’est pas toujours cérébelleuse. Romberg, proprioception, réflexes et conductions <span class=\"nc-red nc-bold\">sensitives</span> aident à reconnaître l’origine périphérique.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Modalités diagnostiques et distinction avec une ataxie cérébelleuse complétées.</p></details>","frequence":0},{"id":"96-5","rang":"A","rubrique":"Diagnostic positif","titre":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","contenu":"<div class=\"notion-course\"><h4>La SLA associe <span class=\"nc-yellow_bg\">atteinte</span> <span class=\"nc-red nc-bold\">motrice</span> centrale et périphérique</h4><table><thead><tr><th>Élément</th><th>Neuropathie périphérique</th><th>SLA / maladie du motoneurone</th></tr></thead><tbody><tr><td>Sensibilité</td><td>Souvent <span class=\"nc-yellow_bg\">atteinte</span>, mais certaines neuropathies sont <span class=\"nc-red nc-bold\">motrices</span> pures.</td><td>Habituellement préservée cliniquement ; un <span class=\"nc-blue_bg\">déficit sensitif</span> net fait rechercher une autre cause.</td></tr><tr><td>Motricité</td><td>Faiblesse, <span class=\"nc-red nc-bold\">amyotrophie</span>, <span class=\"nc-blue_bg\">fasciculations</span> possibles selon mécanisme.</td><td><span class=\"nc-yellow_bg\">Atteinte</span> <span class=\"nc-red nc-bold\">motrice</span> progressive souvent <span class=\"nc-red nc-bold\">asymétrique</span>, avec signes périphériques et centraux dans différentes régions.</td></tr><tr><td>Réflexes / pyramidal</td><td>Souvent diminués ; pas de Babinski attribuable à la neuropathie seule.</td><td>Réflexes anormalement vifs dans un territoire amyotrophique, spasticité et Babinski possibles ; leur absence initiale n’exclut pas une forme débutante.</td></tr><tr><td><span class=\"nc-green nc-bold\">ENMG</span></td><td>Axonal, démyélinisant ou blocs selon cause ; conductions <span class=\"nc-red nc-bold\">sensitives</span> parfois anormales.</td><td>Dénervation active et chronique dans plusieurs régions, conductions <span class=\"nc-red nc-bold\">sensitives</span> généralement préservées ; pas de bloc <span class=\"nc-red nc-bold\">moteur</span> focal typique explicatif.</td></tr></tbody></table><h4>Ne pas manquer la neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale à blocs</h4><ul><li><span class=\"nc-blue_bg\">Déficit moteur</span> pur, distal et <span class=\"nc-red nc-bold\">asymétrique</span>, prédominant souvent aux <span class=\"nc-blue_bg\">membres supérieurs</span> ; <span class=\"nc-red nc-bold\">amyotrophie</span> et <span class=\"nc-blue_bg\">fasciculations</span> possibles.</li><li><span class=\"nc-blue_bg\">ENMG</span> : <span class=\"nc-red nc-bold\">blocs de conduction</span> moteurs hors zones habituelles de <span class=\"nc-red nc-bold\">compression</span> ; leur recherche nécessite un examen adapté. Des anticorps anti-GM1 peuvent appuyer le diagnostic sans être toujours présents.</li><li>Pas de syndrome pyramidal authentique ni d’<span class=\"nc-yellow_bg\">atteinte</span> bulbaire typique ; certains réflexes peuvent rester vifs.</li><li>Traitement spécialisé par immunoglobulines ; les <span class=\"nc-pink_bg\">corticoïdes</span> ne constituent pas le traitement de cette neuropathie et peuvent l’aggraver.</li></ul><div class=\"callout\"><p><span class=\"nc-blue_bg\">Fasciculations</span> seules ≠ SLA. L’absence de trouble <span class=\"nc-red nc-bold\">sensitif</span> n’oppose pas automatiquement SLA et neuropathie : la neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale est un différentiel traitable.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Différentiel SLA–neuropathie motrice précisé sans test isolé présenté comme diagnostique.</p></details>","frequence":2},{"id":"96-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les étiologies des principales polyneuropathies axonales longueur-dépendantes","contenu":"<div class=\"notion-course\"><h4>Causes fréquentes d’une polyneuropathie <span class=\"nc-red nc-bold\">axonale</span> <span class=\"nc-red nc-bold\">distale</span></h4><table><thead><tr><th>Cause</th><th>Contexte / points clés</th></tr></thead><tbody><tr><td>Diabète</td><td><span class=\"nc-yellow_bg\">Atteinte</span> sensitive <span class=\"nc-red nc-bold\">distale</span> <span class=\"nc-red nc-bold\">symétrique</span>, parfois <span class=\"nc-red nc-bold\">douloureuse</span> puis déficitaire ; dépistage <span class=\"nc-green nc-bold\">clinique</span> et examen des <span class=\"nc-blue_bg nc-bold\">pieds</span>. Ne pas attribuer au diabète une forme <span class=\"nc-red nc-bold\">asymétrique</span>, <span class=\"nc-red nc-bold\">proximale</span>, <span class=\"nc-red nc-bold\">motrice</span> pure ou rapidement progressive sans bilan.</td></tr><tr><td><span class=\"nc-orange_bg\">Alcool</span> et dénutrition</td><td><span class=\"nc-yellow_bg\">Atteinte</span> <span class=\"nc-red nc-bold\">distale</span> sensitive <span class=\"nc-red nc-bold\">douloureuse</span>, souvent progressive ; toxicité et carences, notamment B1, peuvent coexister. Une forme aiguë carentielle nécessite une prise en charge rapide.</td></tr><tr><td><span class=\"nc-orange_bg\">Insuffisance rénale</span> chronique</td><td>Contexte d’<span class=\"nc-yellow_bg\">atteinte</span> rénale avancée ; polyneuropathie sensitivomotrice <span class=\"nc-red nc-bold\">distale</span>.</td></tr><tr><td>Médicaments neurotoxiques</td><td>Chimiothérapies, certains anti-infectieux et autres médicaments selon exposition ; reconstituer molécules, doses cumulées et chronologie.</td></tr><tr><td>Carences</td><td>B12, notamment malabsorption, régime à risque ou metformine ; B1 si dénutrition. Une carence B12 peut aussi donner une <span class=\"nc-yellow_bg\">atteinte</span> médullaire.</td></tr></tbody></table><h4>Développer le cours Notion : neuropathie <span class=\"nc-orange_bg\">diabétique</span></h4><ul><li><span class=\"nc-blue_bg\">Paresthésies</span>, <span class=\"nc-blue_bg\">brûlures</span> et allodynie des <span class=\"nc-blue_bg nc-bold\">pieds</span> ; hypoesthésie en chaussettes, achilléens diminués, puis déficit distal. Une <span class=\"nc-yellow_bg\">atteinte</span> isolée des <span class=\"nc-purple nc-bold\">petites fibres</span> peut avoir un <span class=\"nc-green nc-bold\">ENMG</span> <span class=\"nc-green_bg\">normal</span>.</li><li>Dysautonomie : hypotension orthostatique, <span class=\"nc-red_bg\">gastroparésie</span>, <span class=\"nc-red_bg\">troubles</span> du transit, <span class=\"nc-yellow_bg\">vessie rétentionnelle</span>, <span class=\"nc-red_bg\">troubles</span> sexuels et sudation ; rechercher les symptômes selon le contexte.</li><li>Le monofilament de 10 g évalue surtout la perte de sensibilité protectrice et le risque de plaie ; il n’exclut pas une neuropathie débutante/<span class=\"nc-purple nc-bold\">petites fibres</span>. Le DN4 aide à caractériser la douleur, sans confirmer seul la neuropathie.</li><li>Déformations, perte de sensibilité et appuis anormaux favorisent les plaies. Un pied chaud, rouge et gonflé avec neuropathie peut évoquer une neuroarthropathie de Charcot : évaluation rapide, protection et décharge, sans attendre une déformation majeure.</li><li>Prise en charge : équilibre métabolique individualisé, correction des facteurs associés, prévention du pied à risque, rééducation et traitement spécifique de la douleur neuropathique si besoin.</li></ul><p>Les formes focales, l’<span class=\"nc-yellow_bg\">atteinte</span> oculomotrice et la radiculoplexopathie <span class=\"nc-orange_bg\">diabétique</span> <span class=\"nc-red nc-bold\">douloureuse</span> <span class=\"nc-red nc-bold\">proximale</span> sont d’autres présentations : elles ne sont pas une simple extension de la polyneuropathie <span class=\"nc-red nc-bold\">distale</span>.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418174b5f2fc2187a2b539?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathie diabétique</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-2-item-76-addiction-a-lalcool-complications-neurologiques-de-lalcoolisme\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Complications neurologiques de l’alcool</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Diagnostic des neuropathies — synthèse et arbre, 2007</a></li></ul><p>Cours diabétique réintégré ; ENMG non systématique de dépistage et monofilament non exclusif du diagnostic.</p></details>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/charcot-joint","label":"Radiopaedia : Charcot joint (arthropathie neurogène)"}]},{"id":"96-7","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des polyneuropathies axonales longueur-dépendantes plus rares","contenu":"<div class=\"notion-course\"><h4>Causes moins fréquentes à rechercher avec des indices</h4><table><thead><tr><th>Groupe</th><th>Indices / confirmation orientée</th></tr></thead><tbody><tr><td><span class=\"nc-orange_bg\">Amylose</span></td><td>Neuropathie progressive, <span class=\"nc-blue_bg\">douleurs</span>/<span class=\"nc-purple nc-bold\">petites fibres</span> puis déficit, dysautonomie, canal carpien bilatéral, signes cardiaques ou rénaux. Distinguer AL liée à un clone plasmocytaire et ATTR liée à la <span class=\"nc-pink nc-bold\">transthyrétine</span>, héréditaire ou non. Typage indispensable.</td></tr><tr><td>Autres toxiques / médicaments</td><td>Exposition professionnelle ou environnementale, chimiothérapies, <span class=\"nc-pink_bg\">amiodarone</span>, <span class=\"nc-pink_bg\">métronidazole</span> prolongé, <span class=\"nc-pink_bg\">nitrofurantoïne</span>, <span class=\"nc-pink_bg\">disulfirame</span>… Le profil et le risque dépendent de la molécule et de la dose.</td></tr><tr><td>Infection</td><td>VIH selon contexte ; autres infections selon exposition et phénotype. Pas de sérologies <span class=\"nc-yellow_bg\">multiples</span> non ciblées.</td></tr><tr><td>Affection systémique</td><td><span class=\"nc-orange_bg\">Vascularite</span> parfois devenue confluente, maladie inflammatoire, <span class=\"nc-orange_bg\">sarcoïdose</span> ; chercher douleur, asymétrie initiale et signes généraux.</td></tr><tr><td>Endocrinienne / carentielle</td><td>Dysthyroïdie, carences nutritionnelles/malabsorption ; bilan orienté.</td></tr><tr><td>Héréditaire</td><td>Formes axonales de <span class=\"nc-yellow_bg\">Charcot-Marie-Tooth</span> : évolution ancienne, <span class=\"nc-blue_bg\">pieds creux</span>, <span class=\"nc-red nc-bold\">amyotrophie</span> <span class=\"nc-red nc-bold\">distale</span>, histoire familiale parfois absente.</td></tr></tbody></table><h4>Comment ne pas passer à côté de l’<span class=\"nc-orange_bg\">amylose</span></h4><p>Une dysautonomie importante ou une progression inexpliquée doit faire réexaminer l’attribution au diabète. Le bilan associe recherche d’un composant monoclonal, explorations d’organes, prélèvement/typage des dépôts ou génétique TTR selon l’hypothèse et le centre expert. Une biopsie nerveuse n’est pas automatiquement le premier prélèvement.</p><div class=\"callout\"><p>« <span class=\"nc-orange_bg\">Amylose primaire</span> = TTR » et « <span class=\"nc-orange_bg\">amylose</span> secondaire = gammapathie » sont des raccourcis incorrects. AL et ATTR désignent des <span class=\"nc-green_bg nc-bold\">protéines</span> et des mécanismes différents.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418174b5f2fc2187a2b539?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathie diabétique</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Classification amyloïde corrigée ; causes rares reliées à des signes d’appel.</p></details>","frequence":0},{"id":"96-8","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des principales polyneuropathies démyélinisantes","contenu":"<div class=\"notion-course\"><h4>L’ENMG identifie le mécanisme, puis le contexte oriente</h4><table><thead><tr><th>Cause</th><th>Phénotype évocateur</th><th>Point de vigilance</th></tr></thead><tbody><tr><td>Guillain-Barré</td><td>Faiblesse <span class=\"nc-red nc-bold\">aiguë</span> progressive, <span class=\"nc-blue_bg\">aréflexie</span>, possible <span class=\"nc-yellow_bg\">atteinte</span> crânienne/autonome.</td><td>Urgence ; toutes les formes ne sont pas démyélinisantes. Voir item 97 pour la prise en charge dédiée.</td></tr><tr><td>PIDC</td><td>Déficit proximal et distal, <span class=\"nc-red_bg\">troubles</span> sensitifs, <span class=\"nc-blue_bg\">aréflexie</span> ; progression/rechutes au-delà de 8 semaines, variantes possibles.</td><td>Diagnostic neurologique avec critères électrophysiologiques ; protéinorachie élevée seule insuffisante.</td></tr><tr><td>Neuropathie à IgM anti-MAG</td><td><span class=\"nc-yellow_bg\">Atteinte</span> <span class=\"nc-red nc-bold\">distale</span> surtout sensitive, ataxie et parfois tremblement, lente ; IgM monoclonale.</td><td>Dosage et bilan hématologique orientés ; ne pas attribuer toute neuropathie à un pic monoclonal fortuit.</td></tr><tr><td><span class=\"nc-yellow_bg\">Charcot-Marie-Tooth</span> démyélinisante</td><td>Évolution ancienne, déficit/<span class=\"nc-red nc-bold\">amyotrophie</span> <span class=\"nc-red nc-bold\">distale</span>, <span class=\"nc-blue_bg\">pieds creux</span>, histoire familiale possible.</td><td>CMT1A : duplication de PMP22 ; toutes les CMT ne sont pas démyélinisantes.</td></tr><tr><td>HNPP</td><td>Paralysies/compressions récidivantes après pression, plusieurs sites possibles.</td><td>Délétion de PMP22 classiquement ; distinguer d’une mononeuropathie multiple vasculitique.</td></tr><tr><td>Neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale</td><td><span class=\"nc-red nc-bold\">Motrice</span> pure <span class=\"nc-red nc-bold\">asymétrique</span>, surtout <span class=\"nc-blue_bg\">membres supérieurs</span>, blocs hors canaux.</td><td>Traitement spécifique par immunoglobulines ; <span class=\"nc-pink_bg\">corticoïdes</span> potentiellement aggravants.</td></tr></tbody></table><h4>Ne pas confondre « démyélinisant » et « sans axones lésés »</h4><p>Ralentissements marqués, latences prolongées, dispersion et blocs orientent. Une perte <span class=\"nc-red nc-bold\">axonale</span> secondaire peut coexister et aggraver le pronostic. Le spécialiste confronte les mesures à des critères, aux amplitudes et à la température du membre.</p><p>POEMS est une cause rare à évoquer devant neuropathie avec gammapathie et signes systémiques (organomégalie, endocrinopathie, <span class=\"nc-yellow_bg\">atteinte</span> cutanée, lésions osseuses) ; bilan spécialisé.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3261449/en/polyradiculoneuropathie-inflammatoire-demyelinisante-chronique-pidc\" target=\"_blank\" rel=\"noopener noreferrer\">FILNEMUS · PNDS PIDC, 2021 (hébergé par la HAS)</a></li></ul><p>Seuil chronologique actualisé ; CMT axonale/démyélinisante et HNPP distinguées.</p></details>","frequence":0},{"id":"96-9","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des principales neuronopathies","contenu":"<div class=\"notion-course\"><h4>Neuronopathie sensitive : trois causes majeures à connaître</h4><table><thead><tr><th>Cause</th><th>Orientation <span class=\"nc-green nc-bold\">clinique</span> et bilan</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Paranéoplasique</span></td><td>Installation <span class=\"nc-red nc-bold\">subaiguë</span>, <span class=\"nc-blue_bg\">ataxie</span> sensitive multifocale ; cancer pulmonaire à petites cellules notamment, anticorps anti-Hu possibles. Recherche tumorale dirigée et avis spécialisé ; anticorps négatifs n’excluent pas tout syndrome.</td></tr><tr><td>Sjögren / dysimmunité</td><td>Syndrome sec, contexte auto-immun, parfois neuropathie révélatrice avant le syndrome sec. Biologie et examens glandulaires selon arguments.</td></tr><tr><td>Toxique</td><td><span class=\"nc-pink nc-bold\">Sels de platine</span> et excès de vitamine B6 notamment ; vérifier chimiothérapies, compléments et doses.</td></tr></tbody></table><p>Certaines formes restent idiopathiques après bilan. L’absence de diagnostic initial impose une surveillance adaptée si le tableau reste évocateur d’une cause <span class=\"nc-red nc-bold\">paranéoplasique</span>.</p><h4><span class=\"nc-yellow_bg\">Neuronopathie motrice</span> : autre logique</h4><ul><li>SLA, amyotrophies spinales et séquelles de poliomyélite figurent parmi les atteintes du motoneurone périphérique selon âge et évolution.</li><li>Une <span class=\"nc-yellow_bg\">atteinte</span> <span class=\"nc-red nc-bold\">motrice</span> pure impose aussi de chercher une neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale traitable et une <span class=\"nc-red nc-bold\">compression</span>/myélopathie.</li><li>La présence de <span class=\"nc-blue_bg\">fasciculations</span> ou d’<span class=\"nc-red nc-bold\">amyotrophie</span> ne permet pas de conclure sans <span class=\"nc-green nc-bold\">clinique</span> complète et ENMG.</li></ul><div class=\"callout\"><p>Les examens suivent le phénotype. Pas de bilan cancérologique ou génétique identique pour toutes les neuropathies.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Causes sensitives et motrices séparées ; bilan non systématique et limites des anticorps explicitées.</p></details>","frequence":0},{"id":"96-10","rang":"A","rubrique":"Etiologies","titre":"Connaître les étiologies des principales mononeuropathies multiples","contenu":"<div class=\"notion-course\"><h4>Plusieurs nerfs atteints : penser au mécanisme</h4><table><thead><tr><th>Mécanisme / cause</th><th>Indices</th></tr></thead><tbody><tr><td><span class=\"nc-orange_bg\">Vascularite</span></td><td><span class=\"nc-yellow_bg\">Atteinte</span> <span class=\"nc-red nc-bold\">axonale</span> ischémique aiguë/<span class=\"nc-red nc-bold\">subaiguë</span>, <span class=\"nc-red nc-bold\">douloureuse</span>, <span class=\"nc-red nc-bold\">asymétrique</span> et par poussées. Peut rester limitée au nerf ou être systémique.</td></tr><tr><td><span class=\"nc-red_bg\">Vascularites</span> systémiques</td><td><span class=\"nc-orange_bg\">Périartérite noueuse</span>, <span class=\"nc-red_bg\">vascularites</span> associées aux ANCA, <span class=\"nc-pink_bg\">cryoglobulinémie</span> ; rechercher <span class=\"nc-yellow_bg\">atteinte</span> rénale, cutanée, ORL/pulmonaire selon contexte.</td></tr><tr><td>Maladie auto-immune / inflammatoire</td><td>Sjögren, lupus, <span class=\"nc-orange_bg\">polyarthrite rhumatoïde</span>, <span class=\"nc-orange_bg\">sarcoïdose</span> ; mécanismes variables, non tous identiques à une <span class=\"nc-orange_bg\">vascularite</span> nécrosante.</td></tr><tr><td>Infection</td><td>VHB, <span class=\"nc-purple_bg\">VHC</span> avec <span class=\"nc-pink_bg\">cryoglobulinémie</span>, <span class=\"nc-purple_bg\">VIH</span> ; <span class=\"nc-purple_bg\">lèpre</span> selon exposition et contexte géographique, parfois nerfs épaissis et lésions cutanées.</td></tr><tr><td>Diabète / compressions <span class=\"nc-yellow_bg\">multiples</span></td><td>Neuropathies focales ou compressions associées ; ne pas attribuer sans bilan une forme <span class=\"nc-red nc-bold\">douloureuse</span> progressive au seul diabète.</td></tr><tr><td>HNPP / mécanisme dysimmunitaire <span class=\"nc-red nc-bold\">moteur</span></td><td>Épisodes après pression pour HNPP ; <span class=\"nc-blue_bg\">déficit moteur</span> pur avec blocs pour neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale. Ce ne sont pas des <span class=\"nc-red_bg\">vascularites</span> par définition.</td></tr></tbody></table><h4>Chercher l’asymétrie même tardivement</h4><p>Le fibulaire commun, l’ulnaire ou d’autres nerfs peuvent être atteints successivement. Une forme confluente peut paraître <span class=\"nc-red nc-bold\">distale</span> <span class=\"nc-red nc-bold\">symétrique</span> ; l’interrogatoire sur la première douleur et le premier déficit, ainsi que l’<span class=\"nc-green nc-bold\">ENMG</span> comparatif, permettent de retrouver la distribution initiale.</p><div class=\"callout\"><p>Mononeuropathies <span class=\"nc-yellow_bg\">multiples</span> est une description topographique, pas un synonyme de <span class=\"nc-orange_bg\">vascularite</span>. Une <span class=\"nc-orange_bg\">vascularite</span> reste une priorité à rechercher dans une forme <span class=\"nc-red nc-bold\">douloureuse</span> rapidement évolutive.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418174b5f2fc2187a2b539?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathie diabétique</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li></ul><p>Correction de la causalité unique attribuée à la vascularite ; causes non vasculitiques conservées.</p></details>","frequence":0},{"id":"96-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence du diagnostic et de la prise en charge des mononeuropathies multiples","contenu":"<div class=\"notion-course\"><h4>Pourquoi agir vite ?</h4><p>Une <span class=\"nc-yellow_bg\">atteinte</span> pluritronculaire <span class=\"nc-red nc-bold\">douloureuse</span>, aiguë ou <span class=\"nc-red nc-bold\">subaiguë</span> et progressive peut traduire une ischémie nerveuse par <span class=\"nc-orange_bg\">vascularite</span>. La perte <span class=\"nc-red nc-bold\">axonale</span> peut laisser des séquelles : ne pas programmer un simple contrôle lointain.</p><ol><li>Coter et dater les déficits, cartographier les nerfs, rechercher extension et retentissement fonctionnel.</li><li>Rechercher <span class=\"nc-yellow_bg\">atteinte</span> systémique : fièvre, amaigrissement, purpura/livedo, arthralgies, <span class=\"nc-yellow_bg\">atteinte</span> rénale, dyspnée ou signes ORL. Vérifier aussi diabète, médicaments, compressions et infections.</li><li>Obtenir un avis neurologique/interniste urgent, avec hospitalisation selon vitesse d’aggravation et atteintes d’organes.</li><li><span class=\"nc-green nc-bold\">ENMG</span> et biologie orientent ; organiser une preuve tissulaire si nécessaire, au site le plus pertinent. Une biopsie neuromusculaire peut être indiquée si la <span class=\"nc-orange_bg\">vascularite</span> reste à documenter.</li><li>Traitement étiologique spécialisé : immunosuppression si <span class=\"nc-orange_bg\">vascularite</span> retenue, traitement d’une infection ou d’une autre cause si nécessaire. Prélever avant traitement lorsque possible, sans retarder la prise en charge d’une menace d’organe.</li></ol><h4>Biopsie : une indication raisonnée</h4><p>Choisir un <span class=\"nc-green nc-bold\">nerf sensitif</span> <span class=\"nc-green nc-bold\">atteint</span> cliniquement et électriquement, parfois associé à une biopsie musculaire. Risques : <span class=\"nc-blue_bg\">déficit sensitif</span> séquellaire, douleur et cicatrisation. Ce n’est pas un examen de première intention de toute neuropathie ; une autre preuve tissulaire peut éviter le prélèvement nerveux.</p><div class=\"callout\"><p>Ne pas lancer des <span class=\"nc-pink_bg\">corticoïdes</span> pour toute mononeuropathie multiple : infection, <span class=\"nc-red nc-bold\">compression</span> et neuropathie <span class=\"nc-red nc-bold\">motrice</span> à blocs demandent une autre stratégie.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Diagnostic des neuropathies — synthèse et arbre, 2007</a></li></ul><p>Séquence urgente et place de la biopsie complétées ; traitement dépendant du mécanisme.</p></details>","frequence":0},{"id":"96-12","rang":"B","rubrique":"Examens complémentaires","titre":"Avoir une stratégie d’utilisation des examens complémentaires","contenu":"<div class=\"notion-course\"><h4>1. Partir du phénotype, pas d’un bilan exhaustif</h4><p>L’interrogatoire et l’examen recherchent d’abord une cause cohérente. Dans une neuropathie <span class=\"nc-orange_bg\">diabétique</span> <span class=\"nc-red nc-bold\">distale</span> typique stable, le dépistage est <span class=\"nc-green nc-bold\">clinique</span> ; l’<span class=\"nc-green nc-bold\">ENMG</span> n’est pas systématique. En cas de doute, atypie, progression, déficit important ou cause inconnue : avis neurologique et <span class=\"nc-green nc-bold\">ENMG</span>.</p><h4>2. Comprendre ce que l’ENMG apporte</h4><table><thead><tr><th>Profil</th><th>Résultats évocateurs</th></tr></thead><tbody><tr><td>Axonal</td><td>Amplitudes <span class=\"nc-red nc-bold\">sensitives</span>/<span class=\"nc-red nc-bold\">motrices</span> réduites ; vitesses relativement conservées ou modérément ralenties. Détection : dénervation active et recrutement réduit selon <span class=\"nc-yellow_bg\">atteinte</span> et délai.</td></tr><tr><td>Démyélinisant</td><td>Ralentissements marqués, latences distales/ondes F prolongées, dispersion temporelle et blocs ; critères spécialisés nécessaires.</td></tr><tr><td><span class=\"nc-red nc-bold\">Bloc de conduction</span></td><td>La réponse <span class=\"nc-red nc-bold\">motrice</span> après stimulation <span class=\"nc-red nc-bold\">proximale</span> diminue anormalement par rapport à la stimulation <span class=\"nc-red nc-bold\">distale</span>, après prise en compte de la dispersion et des paramètres techniques.</td></tr><tr><td>Neuronopathie sensitive</td><td>Potentiels sensitifs diffusément réduits/absents, non longueur-dépendants ; paramètres moteurs relativement préservés.</td></tr><tr><td><span class=\"nc-purple nc-bold\">Petites fibres</span></td><td>ENMG standard parfois <span class=\"nc-green_bg\">normal</span> car il explore surtout les grosses <span class=\"nc-purple nc-bold\">fibres</span> ; explorations spécialisées, éventuellement biopsie cutanée, selon tableau.</td></tr></tbody></table><h4>3. Choisir la biologie et les examens ciblés</h4><ul><li>Premier niveau selon contexte : <span class=\"nc-pink nc-bold\">glycémie</span>/HbA1c, <span class=\"nc-blue_bg\">NFS</span>, fonction rénale, <span class=\"nc-blue_bg\">bilan hépatique</span>, TSH, marqueurs inflammatoires ; rechercher B12 et composant monoclonal selon phénotype/risque et avis.</li><li>Si mononeuropathies <span class=\"nc-yellow_bg\">multiples</span>/<span class=\"nc-orange_bg\">vascularite</span> : urines et fonction rénale, inflammation, ANCA, cryoglobulines, <span class=\"nc-pink_bg\">complément</span> et sérologies dirigées selon suspicion.</li><li>LCS : surtout suspicion de polyradiculoneuropathie, méningoradiculite ou infiltration. <span class=\"nc-red_bg\">Hyperprotéinorachie isolée</span> non spécifique ; normalité précoce n’exclut pas Guillain-Barré.</li><li>Génétique : forme héréditaire probable ou cause ciblée, avec conseil adapté. Biopsie nerveuse : indications sélectionnées, surtout <span class=\"nc-orange_bg\">vascularite</span> ou neuropathie évolutive inexpliquée ; pas en routine.</li><li>Imagerie : <span class=\"nc-red nc-bold\">compression</span>, plexus, cause centrale ou recherche étiologique ciblée, pas IRM systématique de toutes les polyneuropathies.</li></ul><div class=\"callout\"><p>Dans les urgences, les examens se coordonnent avec la prise en charge : ils ne doivent pas différer la surveillance respiratoire, l’IRM d’une <span class=\"nc-red nc-bold\">compression</span> ou l’avis pour <span class=\"nc-orange_bg\">vascularite</span>.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathies diffuses (96)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418174b5f2fc2187a2b539?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Neuropathie diabétique</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Chapitre 8 — Items 95, 96 et 97</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Diagnostic des neuropathies — synthèse et arbre, 2007</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3261449/en/polyradiculoneuropathie-inflammatoire-demyelinisante-chronique-pidc\" target=\"_blank\" rel=\"noopener noreferrer\">FILNEMUS · PNDS PIDC, 2021 (hébergé par la HAS)</a></li></ul><p>Sens du bloc proximal/distal corrigé ; ENMG non absolu, bilan hiérarchisé et limites explicités.</p></details>","frequence":4}],"astuces":[{"type":"warning","titre":"La chronologie compte","contenu":"<div class=\"notion-course\"><p>Faiblesse rapide, <span class=\"nc-yellow_bg\">atteinte</span> respiratoire/bulbaire ou déficit multifocal douloureux : ne pas attendre un bilan ambulatoire complet.</p></div>"},{"type":"warning","titre":"Le diabète n’explique pas tout","contenu":"<div class=\"notion-course\"><p>Asymétrie, déficit proximal, progression rapide ou motricité pure imposent de revoir l’attribution.</p></div>"},{"type":"info","titre":"Bloc : proximal plus petit que distal","contenu":"<div class=\"notion-course\"><p>Après contrôle technique, la baisse de réponse à la stimulation <span class=\"nc-red nc-bold\">proximale</span> oriente vers un <span class=\"nc-red nc-bold\">bloc de conduction</span>.</p></div>"},{"type":"info","titre":"Un différentiel traitable de SLA","contenu":"<div class=\"notion-course\"><p>La neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale à blocs peut donner <span class=\"nc-red nc-bold\">amyotrophie</span> et <span class=\"nc-blue_bg\">fasciculations</span> ; rechercher les blocs hors canaux.</p></div>"}],"strategie":{"urgence":"<div class=\"notion-course\"><ul><li>Évaluer respiration, déglutition, dysautonomie et vitesse de progression.</li><li>Mononeuropathies <span class=\"nc-yellow_bg\">multiples</span> douloureuses évolutives : avis urgent et recherche de <span class=\"nc-orange_bg\">vascularite</span>/<span class=\"nc-yellow_bg\">atteinte</span> d’organes.</li></ul></div>","redflags":"<div class=\"notion-course\"><ul><li>Déficit rapidement progressif, dyspnée, fausses routes, dysautonomie sévère.</li><li>Asymétrie <span class=\"nc-red nc-bold\">douloureuse</span>, fièvre, purpura, <span class=\"nc-yellow_bg\">atteinte</span> rénale ou pulmonaire.</li><li>Signes centraux/niveau <span class=\"nc-red nc-bold\">sensitif</span> ou <span class=\"nc-red_bg\">troubles</span> sphinctériens récents : chercher une <span class=\"nc-red nc-bold\">compression</span>.</li></ul></div>","principes":"<div class=\"notion-course\"><ul><li>Localiser → décrire <span class=\"nc-purple nc-bold\">fibres</span> et évolution → ENMG si indiqué → bilan étiologique ciblé.</li><li>Distinguer axonal, démyélinisant et neuronal ; ne pas confondre phénotype et cause.</li><li>Suivi fonctionnel, prévention des chutes/plaies et traitement causal ou symptomatique adapté.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre","label":"CEN · Chapitre 8 — Items 95, 96 et 97 ↗"},{"href":"https://www.has-sante.fr/upload/docs/application/pdf/neuropathies_peripheriques_synthese.pdf","label":"HAS · Diagnostic des neuropathies — synthèse et arbre, 2007 ↗"},{"href":"https://www.has-sante.fr/jcms/p_3261449/en/polyradiculoneuropathie-inflammatoire-demyelinisante-chronique-pidc","label":"FILNEMUS · PNDS PIDC, 2021 (hébergé par la HAS) ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-2-item-76-addiction-a-lalcool-complications-neurologiques-de-lalcoolisme","label":"CEN · Complications neurologiques de l’alcool ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Reconnaître et localiser l’atteinte","detail":"<ul><li>Examiner force, sensibilité, réflexes et marche.</li><li>Préciser évolution, respiration et déglutition.</li><li>Rechercher signes centraux, niveau sensitif et symptômes sphinctériens récents.</li></ul>","branches":[{"label":"Progression rapide, respiration/bulbaire ou dysautonomie sévère","to":"urgent"},{"label":"Signes centraux ou localisation incertaine","to":"central"},{"label":"Atteinte périphérique sans urgence vitale immédiate","to":"distribution"}]},{"id":"urgent","kind":"urgent","label":"Organiser l’évaluation hospitalière urgente","detail":"<ul><li>Surveiller fonctions respiratoires, bulbaires et autonomes.</li><li>Avis neurologique sans attendre ENMG ou PL complets.</li><li>Faiblesse aiguë progressive : Guillain-Barré notamment.</li><li>Les examens peuvent être non concluants au début ; l’évolution clinique prime.</li></ul>","branches":[]},{"id":"central","kind":"uncertain","label":"Rechercher une cause centrale ou mixte","detail":"<ul><li>Réexaminer et adapter l’imagerie.</li><li>Avis urgent si compression ou déficit aigu suspecté.</li><li>Babinski, niveau sensitif, trouble sphinctérien récent ou installation brutale changent le raisonnement.</li><li>Une carence B12 peut associer atteinte médullaire et neuropathie.</li></ul>","branches":[]},{"id":"distribution","kind":"decision","label":"Quel phénotype clinique domine ?","detail":"<ul><li>Cartographier symétrie, nerfs et groupes musculaires.</li><li>Distinguer sensitif, moteur et mixte.</li><li>La distribution est un point de départ, pas encore une étiologie.</li></ul>","branches":[{"label":"Distal symétrique, pieds avant mains","to":"poly"},{"label":"Un ou plusieurs troncs nerveux","to":"troncs"},{"label":"Proximal et distal, aréflexie diffuse","to":"prn"},{"label":"Sensitif non longueur-dépendant ou moteur pur","to":"neuronal"}]},{"id":"poly","kind":"decision","label":"Polyneuropathie : préciser le mécanisme","detail":"<ul><li>Rechercher causes fréquentes et signes atypiques.</li><li>ENMG si caractérisation nécessaire.</li><li>Diabète typique stable : dépistage clinique, pas d’ENMG systématique.</li><li>Ataxie/tremblement, pieds creux ou dysautonomie modifient les hypothèses.</li></ul>","branches":[{"label":"Profil axonal longueur-dépendant","to":"axonal"},{"label":"Profil démyélinisant","to":"demyelin"},{"label":"Douleurs de petites fibres, ENMG normal","to":"petites"}]},{"id":"axonal","kind":"finish","label":"Chercher les causes axonales cohérentes","detail":"<ul><li>Diabète, alcool, rein, médicaments et carences.</li><li>Élargir si atypie ou absence d’explication.</li><li>Dysautonomie/canal carpien bilatéral : penser amylose selon contexte.</li><li>Histoire ancienne/pieds creux : forme héréditaire possible.</li><li>Utiliser le second arbre pour hiérarchiser le bilan.</li></ul>","branches":[]},{"id":"demyelin","kind":"finish","label":"Orienter le bilan démyélinisant","detail":"<ul><li>Confronter ENMG, durée et phénotype.</li><li>Demander avis neurologique spécialisé.</li><li>Ataxie distale + IgM : anti-MAG possible ; déficit proximal/distal chronique : PIDC.</li><li>CMT démyélinisante si évolution ancienne ; HNPP si épisodes aux compressions.</li><li>Une protéinorachie élevée seule ne confirme pas une PIDC.</li></ul>","branches":[]},{"id":"petites","kind":"finish","label":"Ne pas exclure la neuropathie","detail":"<ul><li>Rechercher thermoalgie et dysautonomie.</li><li>Discuter explorations spécialisées.</li><li>L’ENMG usuel peut rester normal ; tester selon les fibres et le contexte.</li><li>Rechercher diabète, médicaments ou autre cause plausible.</li></ul>","branches":[]},{"id":"troncs","kind":"decision","label":"Un nerf ou plusieurs territoires ?","detail":"<ul><li>Reconstituer l’ordre d’apparition.</li><li>Repérer douleur et sites de compression.</li><li>Une forme confluente peut masquer l’asymétrie initiale.</li></ul>","branches":[{"label":"Un nerf à un site compressif plausible","to":"mono"},{"label":"Plusieurs nerfs douloureux, déficit évolutif","to":"vasculite"},{"label":"Moteur pur asymétrique, surtout mains/bras","to":"moteur"}]},{"id":"mono","kind":"finish","label":"Explorer la mononeuropathie","detail":"<ul><li>Chercher compression ou traumatisme.</li><li>ENMG/imagerie ciblés si doute ou déficit.</li><li>Voir item 95. Une atteinte aiguë douloureuse hors site compressif peut annoncer une mononeuropathie multiple.</li></ul>","branches":[]},{"id":"vasculite","kind":"urgent","label":"Rechercher une vascularite en urgence","detail":"<ul><li>Avis neuro/interniste et bilan d’atteinte d’organes.</li><li>ENMG puis preuve étiologique adaptée.</li><li>Chercher purpura, atteinte rénale/pulmonaire, inflammation et infection.</li><li>Biopsie ciblée si nécessaire ; traitement spécialisé sans retarder une menace d’organe.</li><li>Mononeuropathies multiples ne signifie pas toujours vascularite : vérifier le mécanisme.</li></ul>","branches":[]},{"id":"prn","kind":"decision","label":"Préciser la chronologie et la gravité","detail":"<ul><li>Rechercher progression, rechutes et atteinte crânienne.</li><li>Organiser ENMG et LCS selon avis.</li><li>Ne pas attendre une dissociation albuminocytologique pour adresser une forme aiguë.</li></ul>","branches":[{"label":"Installation aiguë ou aggravation rapide","to":"aigue"},{"label":"Évolution > 8 semaines / rechutes, sans urgence actuelle","to":"pidc"}]},{"id":"aigue","kind":"urgent","label":"Évoquer Guillain-Barré et hospitaliser","detail":"<ul><li>Évaluer respiration, déglutition et dysautonomie.</li><li>Coordonner le bilan avec la surveillance.</li><li>Le syndrome peut être axonal ou démyélinisant.</li><li>L’item 97 détaille ce parcours ; ne pas attendre les résultats pour protéger les fonctions vitales.</li></ul>","branches":[]},{"id":"pidc","kind":"finish","label":"Rechercher une PIDC ou une autre cause","detail":"<ul><li>Avis spécialisé et critères électrocliniques.</li><li>Écarter causes héréditaires et autres diagnostics possibles.</li><li>Seuil du PNDS : évolution au-delà de 8 semaines.</li><li>La gravité fonctionnelle ou respiratoire peut imposer une prise en charge urgente même dans une forme chronique.</li></ul>","branches":[]},{"id":"neuronal","kind":"decision","label":"Sensitive ou motrice pure ?","detail":"<ul><li>Tester proprioception, force et signes pyramidaux.</li><li>ENMG étendu selon la question.</li><li>L’ataxie peut être sensitive ; les fasciculations ne suffisent pas à affirmer une SLA.</li></ul>","branches":[{"label":"Sensitif non longueur-dépendant / ataxie","to":"ganglion"},{"label":"Moteur pur / amyotrophie","to":"moteur"}]},{"id":"ganglion","kind":"finish","label":"Chercher une neuronopathie sensitive","detail":"<ul><li>Confirmer l’atteinte sensitive diffuse à l’ENMG.</li><li>Bilan paranéoplasique, Sjögren ou toxique selon contexte.</li><li>Anti-Hu et cancer pulmonaire, syndrome sec, platines/excès de B6.</li><li>Choix du bilan et du suivi avec le spécialiste ; pas de panel identique pour tous.</li></ul>","branches":[]},{"id":"moteur","kind":"finish","label":"Écarter une neuropathie motrice traitable","detail":"<ul><li>Chercher blocs de conduction hors canaux.</li><li>Rechercher signes centraux et extension régionale.</li><li>Blocs + déficit moteur pur : neuropathie motrice multifocale possible, immunoglobulines spécialisées.</li><li>Signes centraux et périphériques progressifs : évoquer maladie du motoneurone après exclusion des autres causes.</li><li>Pas de corticoïdes empiriques pour la neuropathie motrice multifocale.</li></ul>","branches":[]}]},"cards":[{"i":"6569a51004f1","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quel est le piège diagnostique classique concernant les polyneuropathies axonales longueur-dépendantes, notamment chez le diabétique âgé ?","a":"<div class=\"notion-course\"><p>Ne pas attribuer toute faiblesse ou douleur au diabète ou à l’âge. Une <span class=\"nc-yellow_bg\">atteinte</span> rapidement progressive, <span class=\"nc-red nc-bold\">asymétrique</span>, <span class=\"nc-red nc-bold\">proximale</span>, <span class=\"nc-red nc-bold\">motrice</span> pure ou avec signes centraux impose une autre recherche étiologique.</p></div>"},{"i":"90f51fafa371","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quels sont les principaux signes cliniques évoquant un syndrome neurogène périphérique ?","a":"<div class=\"notion-course\"><p>Faiblesse flasque, hypotonie, réflexes diminués, <span class=\"nc-red nc-bold\">amyotrophie</span> parfois retardée ; <span class=\"nc-red_bg\">troubles</span> sensitifs et autonomes selon <span class=\"nc-purple nc-bold\">fibres</span>. L’association peut être incomplète : pas de triade obligatoire.</p></div>"},{"i":"bc449e67f3c4","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quelle est la première étape de la démarche diagnostique d'une neuropathie périphérique ?","a":"<div class=\"notion-course\"><p>Reconnaître une <span class=\"nc-yellow_bg\">atteinte</span> périphérique, rechercher les urgences et la localiser cliniquement. Puis préciser mécanisme par l’<span class=\"nc-green nc-bold\">ENMG</span> si indiqué et rechercher la cause adaptée au phénotype.</p></div>"},{"i":"fd3d3f41c3fd","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Face à une suspicion de neuropathie périphérique, quels éléments de l'interrogatoire et de l'examen clinique doivent être systématiquement recherchés ?","a":"<div class=\"notion-course\"><p>Début/évolution, symétrie et distribution, <span class=\"nc-purple nc-bold\">fibres</span> atteintes, douleur et dysautonomie ; diabète, <span class=\"nc-orange_bg\">alcool</span>, fonction rénale, médicaments/toxiques, nutrition et famille. Examen <span class=\"nc-red nc-bold\">moteur</span>, <span class=\"nc-red nc-bold\">sensitif</span>, réflexes, marche, <span class=\"nc-blue_bg nc-bold\">pieds</span> et signes centraux.</p></div>"},{"i":"23bc0ef10caf","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les caractéristiques topographiques et cliniques d'une polyneuropathie ?","a":"<div class=\"notion-course\"><p>Forme habituelle longueur-dépendante : <span class=\"nc-red nc-bold\">distale</span>, <span class=\"nc-red nc-bold\">bilatérale</span>, relativement <span class=\"nc-red nc-bold\">symétrique</span>, pieds avant <span class=\"nc-blue_bg\">mains</span> ; symptômes sensitifs souvent initiaux, achilléens diminués, déficit distal possible. Il existe des variantes.</p></div>"},{"i":"98474d1e2c66","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les quatre questions clés à se poser devant tout déficit neurologique distal pour orienter le diagnostic topographique d'une neuropathie diffuse ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Symétrique</span> ou <span class=\"nc-red nc-bold\">asymétrique</span> ? Distal ou proximal ? Un ou plusieurs nerfs, racines ou distribution non longueur-dépendante ? <span class=\"nc-red nc-bold\">Moteur</span> pur, <span class=\"nc-red nc-bold\">sensitif</span> ou mixte ? Ajouter le mode d’installation.</p></div>"},{"i":"d10d4bb75f93","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les caractéristiques cliniques et paracliniques d'une polyradiculonévrite ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Atteinte des</span> racines et nerfs, <span class=\"nc-red nc-bold\">proximale</span> et <span class=\"nc-red nc-bold\">distale</span>, souvent <span class=\"nc-red nc-bold\">bilatérale</span> avec <span class=\"nc-blue_bg nc-bold\">aréflexie</span>, possible <span class=\"nc-yellow_bg\">atteinte</span> crânienne/autonome. <span class=\"nc-green nc-bold\">ENMG</span> et LCS aident ; leur normalité précoce n’exclut pas une forme <span class=\"nc-red nc-bold\">aiguë</span>. Évaluer respiration/déglutition.</p></div>"},{"i":"fd2c6aea8de5","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Comment distinguer une mononeuropathie d'une mononeuropathie multiple sur le plan clinique ?","a":"<div class=\"notion-course\"><p>Mononeuropathie : un nerf. <span class=\"nc-yellow_bg\">Multiples</span> : plusieurs troncs, souvent <span class=\"nc-red nc-bold\">asymétriques</span>/<span class=\"nc-red nc-bold\">asynchrones</span>. Une forme confluente tardive peut sembler symétrique ; douleur et progression font rechercher une <span class=\"nc-orange_bg\">vascularite</span>.</p></div>"},{"i":"15002799e264","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Quelle est la différence fondamentale en termes de sensibilité entre une neuropathie périphérique et une sclérose latérale amyotrophique (SLA) ?","a":"<div class=\"notion-course\"><p>La SLA respecte habituellement la sensibilité. Beaucoup de neuropathies donnent des signes sensitifs, mais certaines sont <span class=\"nc-red nc-bold\">motrices</span> pures : leur absence ne prouve donc pas une SLA.</p></div>"},{"i":"175b68bb94e2","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Comment différencier une sclérose latérale amyotrophique (SLA) d'un diagnostic différentiel comme la Neuropathie Motrice Multifocale avec Blocs de Conduction (NMMBC) en présence de certains signes cliniques fréquents ?","a":"<div class=\"notion-course\"><p>La neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale est <span class=\"nc-red nc-bold\">motrice</span> pure, <span class=\"nc-red nc-bold\">asymétrique</span>, souvent <span class=\"nc-red nc-bold\">distale</span> aux bras, avec blocs hors zones de <span class=\"nc-red nc-bold\">compression</span> et sans syndrome pyramidal authentique. Anti-GM1 parfois présents ; immunoglobulines efficaces. <span class=\"nc-blue_bg\">Fasciculations</span> et <span class=\"nc-red nc-bold\">amyotrophie</span> peuvent exister dans les deux.</p></div>"},{"i":"1d1b0a0c2a7a","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Comment l'examen clinique permet-il de différencier une neuropathie périphérique d'une sclérose latérale amyotrophique (SLA) concernant les motoneurones atteints ?","a":"<div class=\"notion-course\"><p>Une neuropathie donne une <span class=\"nc-yellow_bg\">atteinte</span> périphérique. La SLA associe <span class=\"nc-yellow_bg\">atteinte</span> du motoneurone périphérique et central, parfois dans des régions différentes et de manière progressive ; les signes centraux peuvent être discrets initialement.</p></div>"},{"i":"3893148d8d0a","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Quelles sont les spécificités des réflexes ostéo-tendineux (ROT) et des signes pyramidaux pour distinguer une neuropathie périphérique d'une sclérose latérale amyotrophique (SLA) ?","a":"<div class=\"notion-course\"><p>Neuropathie : ROT souvent diminués, pas de Babinski expliqué par elle seule. SLA : ROT anormalement vifs dans un territoire amyotrophique, spasticité/Babinski possibles. Un réflexe isolé ne suffit pas et peut rester vif dans une neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale.</p></div>"},{"i":"9164cd5bc8a8","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Que révèle l'électromyogramme (ENMG) dans les cas de neuropathie périphérique et de sclérose latérale amyotrophique (SLA) ?","a":"<div class=\"notion-course\"><p>Neuropathie : profil axonal, démyélinisant ou blocs selon cause, <span class=\"nc-yellow_bg\">atteinte</span> sensitive possible. SLA : dénervation active/chronique dans plusieurs régions avec conductions <span class=\"nc-red nc-bold\">sensitives</span> généralement préservées ; rechercher un bloc <span class=\"nc-red nc-bold\">moteur</span> pouvant orienter vers un différentiel traitable.</p></div>"},{"i":"32e715ecdb8e","n":96,"o":"96-1","u":"Définition","t":"Connaître la classification et la définition des différents types de neuropathies périphériques","q":"Quelles dimensions décrire avant de chercher la cause d’une neuropathie ?","a":"<div class=\"notion-course\"><p>Topographie, temporalité, fibres atteintes et mécanisme électrophysiologique. Puis relier ce profil au terrain et aux causes plausibles.</p></div>"},{"i":"277714f50363","n":96,"o":"96-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuronopathie sensitive (examen clinique, démarche diagnostique)","q":"Quels signes orientent vers une neuronopathie sensitive ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Atteinte</span> sensitive non longueur-dépendante, parfois <span class=\"nc-red nc-bold\">asymétrique</span>, <span class=\"nc-blue_bg\">mains</span>/<span class=\"nc-blue_bg\">tronc</span>/face précocement, ataxie et <span class=\"nc-blue_bg\">aréflexie</span>. <span class=\"nc-green nc-bold\">ENMG</span> : potentiels sensitifs réduits diffusément, motricité relativement conservée.</p></div>"},{"i":"16a8ffcd2dcf","n":96,"o":"96-6","u":"Etiologies","t":"Connaître les étiologies des principales polyneuropathies axonales longueur-dépendantes","q":"Quelles causes fréquentes de polyneuropathie axonale distale rechercher ?","a":"<div class=\"notion-course\"><p>Diabète, <span class=\"nc-orange_bg\">alcool</span>/dénutrition, <span class=\"nc-orange_bg\">insuffisance rénale</span>, médicaments neurotoxiques et carences notamment B12. Une cause connue ne suffit pas si le phénotype est atypique.</p></div>"},{"i":"146bf0314a00","n":96,"o":"96-6","u":"Etiologies","t":"Connaître les étiologies des principales polyneuropathies axonales longueur-dépendantes","q":"Le monofilament normal exclut-il une neuropathie diabétique ?","a":"<div class=\"notion-course\"><p>Non. Il recherche surtout la perte de sensibilité protectrice et le risque de plaie. Les <span class=\"nc-purple nc-bold\">petites fibres</span> et formes débutantes peuvent échapper au test ; compléter l’examen <span class=\"nc-green nc-bold\">clinique</span>.</p></div>"},{"i":"fe85291416c8","n":96,"o":"96-7","u":"Etiologies","t":"Connaître les étiologies des polyneuropathies axonales longueur-dépendantes plus rares","q":"Quels indices évoquent une neuropathie amyloïde ?","a":"<div class=\"notion-course\"><p>Progression, <span class=\"nc-blue_bg\">douleurs</span>/<span class=\"nc-purple nc-bold\">petites fibres</span>, dysautonomie importante, canal carpien bilatéral, signes cardiaques/rénaux et parfois antécédents familiaux. Distinguer et typer AL versus ATTR ; pas de biopsie nerveuse automatique.</p></div>"},{"i":"115e3a488ba8","n":96,"o":"96-8","u":"Etiologies","t":"Connaître les étiologies des principales polyneuropathies démyélinisantes","q":"Quand évoquer une PIDC et que ne prouve pas une protéinorachie élevée ?","a":"<div class=\"notion-course\"><p>Évolution progressive ou à rechutes au-delà de 8 semaines, avec déficit souvent proximal/distal et <span class=\"nc-blue_bg\">aréflexie</span>. Confirmation neurologique et <span class=\"nc-green nc-bold\">ENMG</span> ; <span class=\"nc-blue nc-bold\">hyperprotéinorachie</span> seule non diagnostique.</p></div>"},{"i":"906e591980f6","n":96,"o":"96-8","u":"Etiologies","t":"Connaître les étiologies des principales polyneuropathies démyélinisantes","q":"PMP22 : duplication ou délétion ?","a":"<div class=\"notion-course\"><p>Duplication : CMT1A. Délétion : neuropathie héréditaire avec hypersensibilité à la pression (HNPP). Le contexte et l’ENMG orientent avant génétique.</p></div>"},{"i":"773ac6fdd06c","n":96,"o":"96-9","u":"Etiologies","t":"Connaître les étiologies des principales neuronopathies","q":"Quelles causes majeures de neuronopathie sensitive rechercher ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Paranéoplasique</span>, notamment anti-Hu/cancer pulmonaire à petites cellules ; Sjögren ou dysimmunité ; toxiques, notamment <span class=\"nc-pink_bg\">platines</span> et excès de B6. Certaines formes restent idiopathiques.</p></div>"},{"i":"f62f2dc5db87","n":96,"o":"96-10","u":"Etiologies","t":"Connaître les étiologies des principales mononeuropathies multiples","q":"Toute mononeuropathie multiple est-elle une vascularite ?","a":"<div class=\"notion-course\"><p>Non. <span class=\"nc-orange_bg\">Vascularite</span> prioritaire si forme <span class=\"nc-red nc-bold\">douloureuse</span> aiguë/<span class=\"nc-red nc-bold\">subaiguë</span>, mais aussi compressions/<span class=\"nc-orange_bg\">diabète</span>, HNPP, infections, maladies systémiques et neuropathie <span class=\"nc-red nc-bold\">motrice</span> multifocale selon tableau.</p></div>"},{"i":"c18c25d856f6","n":96,"o":"96-11","u":"Identifier une urgence","t":"Connaître l’urgence du diagnostic et de la prise en charge des mononeuropathies multiples","q":"Pourquoi une mononeuropathie multiple douloureuse progressive est-elle urgente ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-orange_bg\">vascularite</span> peut provoquer une perte <span class=\"nc-red nc-bold\">axonale</span> ischémique irréversible. Avis neuro/interniste urgent, recherche d’<span class=\"nc-yellow_bg\">atteinte</span> d’organes, <span class=\"nc-green nc-bold\">ENMG</span> et preuve étiologique adaptés, sans retarder une menace d’organe.</p></div>"},{"i":"2b33296ab99e","n":96,"o":"96-12","u":"Examens complémentaires","t":"Avoir une stratégie d’utilisation des examens complémentaires","q":"Dans quel sens diminue la réponse lors d’un bloc de conduction moteur ?","a":"<div class=\"notion-course\"><p>La réponse obtenue après stimulation <span class=\"nc-red nc-bold\">proximale</span> est anormalement réduite par rapport à celle après stimulation <span class=\"nc-red nc-bold\">distale</span>, après contrôle des critères techniques et de dispersion.</p></div>"},{"i":"be92aa2e07e3","n":96,"o":"96-12","u":"Examens complémentaires","t":"Avoir une stratégie d’utilisation des examens complémentaires","q":"Un ENMG normal exclut-il toute neuropathie ?","a":"<div class=\"notion-course\"><p>Non. Il peut rester <span class=\"nc-green_bg\">normal</span> dans une neuropathie isolée des <span class=\"nc-purple nc-bold\">petites fibres</span> et être non concluant au début de certaines neuropathies aiguës. Interpréter selon <span class=\"nc-green nc-bold\">clinique</span> et délai.</p></div>"},{"i":"51c319db01db","n":96,"o":"96-12","u":"Examens complémentaires","t":"Avoir une stratégie d’utilisation des examens complémentaires","q":"Quand discuter une biopsie nerveuse ?","a":"<div class=\"notion-course\"><p>Indications sélectionnées, surtout <span class=\"nc-yellow_bg\">suspicion de vascularite</span> ou neuropathie évolutive inexpliquée. <span class=\"nc-green nc-bold\">Nerf sensitif</span> <span class=\"nc-green nc-bold\">atteint</span>, avis spécialisé et balance bénéfice–risque ; jamais en routine.</p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418135b724d04cf17df8b0?pvs=204","reviewedAt":"2026-10-12","note":"Cours Notion restructuré, objectifs complétés et références des collèges/HAS vérifiées. Les couleurs conservent celles de tes passages correspondants."}};
